function computePeaks(){peaks=[];const count=1000,channels=Array.from({length:buffer.numberOfChannels},(_,c)=>buffer.getChannelData(c));for(let x=0;x<count;x++){let peak=0,start=Math.floor(x/count*buffer.length),end=Math.floor((x+1)/count*buffer.length);for(let i=start;i<end;i++)for(const ch of channels)peak=Math.max(peak,Math.abs(ch[i]));peaks.push(peak)}}
