const fxFields={filterLow:'lowpass',filterHigh:'highpass',eqBass:'bass',eqMid:'mid',eqTreble:'treble',sectionGain:'gain'};
function editPanel(){const s=current();controls();if(!s){$('selectedTitle').textContent='Select a clip';return}$('selectedTitle').textContent=s.name;$('sectionName').value=s.name;$('sectionEvent').value=s.event;$('sectionKind').value=s.kind;for(const [id,key]of Object.entries({sectionStart:'start',sectionEnd:'end',pickup:'pickup',tail:'tail'}))$(id).value=(s[key]/buffer.sampleRate).toFixed(6);for(const [id,key]of Object.entries(fxFields))$(id).value=s.fx[key];$('approve').checked=s.approved;$('auditionSeam').disabled=s.kind!=='loop';seamReport();drawWave()}
