for(const id of ['sectionEvent','sectionKind'])$(id).onchange=()=>{stop();const s=current();s[id==='sectionEvent'?'event':'kind']=$(id).value;renderList();editPanel()};
for(const id of ['sectionStart','sectionEnd','pickup','tail'])$(id).onchange=()=>{const s=current(),n=Number($(id).value),key={sectionStart:'start',sectionEnd:'end',pickup:'pickup',tail:'tail'}[id],sample=Math.round(n*buffer.sampleRate);if(!Number.isFinite(n)||sample<0||sample>buffer.length||(key==='start'&&sample>=s.end)||(key==='end'&&sample<=s.start)){status('Invalid boundary. Start must be before end and within the file.');editPanel();return}stop();s[key]=sample;boundHandles(s);selection={start:s.start,end:s.end};renderList();editPanel()};
