function fxSettings(){return {lowpass:value('filterLow',100,20000,20000),highpass:value('filterHigh',20,2000,20),bass:value('eqBass',-12,12,0),mid:value('eqMid',-12,12,0),treble:value('eqTreble',-12,12,0),gain:value('sectionGain',-24,0,-6)}}
