$('triggerTo').onclick=safely(async()=>{if(!playback){$('transitionStatus').textContent='Play the from section first.';return}if(pending){$('transitionStatus').textContent='A transition is already scheduled. Stop to cancel or wait for the handoff.';return}const from=sections.find(s=>s.id===playback.sectionId),to=sections.find(s=>s.id===$('toSection').value),ctx=context();if(!to||from.id===to.id){$('transitionStatus').textContent='Choose a different destination section.';return}if(from.kind!=='loop'){ $('transitionStatus').textContent='Use a looping source for this transition audition.';return}const r=ruleSettings(),g=grid(),body=(from.end-from.start)/buffer.sampleRate;const elapsed=Math.max(0,ctx.currentTime-playback.started),lead=Math.max(.06,to.pickup/buffer.sampleRate+.03);let next=A.boundary(elapsed+lead,g.bpm,g.beats,body,r.exit),at=playback.started+next;if(r.exit==='now')at=ctx.currentTime+lead;const fade=Math.min(r.crossfade,body/2,(to.end-to.start)/buffer.sampleRate/2);const v=voice(to,at-to.pickup/buffer.sampleRate,to.start-to.pickup,to.end,to.kind==='loop');const incomingAt=at-to.pickup/buffer.sampleRate;const inDuration=to.pickup?Math.min(fade,to.pickup/buffer.sampleRate):fade;fadeGain(v.fade.gain,incomingAt,inDuration,true,r.fadeCurve);const old=playback.voice;if(r.exit==='end'){old.src.stop(at);if(from.tail>0)voice(from,at,from.end,from.end+from.tail,false)}else{fadeGain(old.fade.gain,at,fade,false,r.fadeCurve);old.src.stop(at+fade+.005)}pending={at,playback:{sectionId:to.id,started:at,voice:v,loop:to.kind==='loop'}};$('transitionStatus').textContent=`Scheduled in ${(at-ctx.currentTime).toFixed(2)}s · ${from.name} → ${to.name}${to.pickup?' · pickup lead-in included':''}`;});
