function fadeGain(param,at,duration,incoming,curve){param.cancelScheduledValues(at);if(!duration){param.setValueAtTime(incoming?1:0,at);return}if(curve==='equal_power'){const values=new Float32Array(65);for(let i=0;i<65;i++)values[i]=incoming?Math.sin(i/64*Math.PI/2):Math.cos(i/64*Math.PI/2);param.setValueCurveAtTime(values,at,duration)}else{param.setValueAtTime(incoming?0:1,at);param.linearRampToValueAtTime(incoming?1:0,at+duration)}}
